cd /private/var/folders/mc/rj708cb13vv9x7hm9rptcwqc0000gn/T/p3-clb5okzy; mkdir -p drafts review-records
cat > drafts/0002-quiz.json <<'EOF'
{
  "id": "0002",
  "objective": "O4",
  "title": "Workflows, agents and who owns the control flow",
  "items": [
    {
      "id": "q1",
      "type": "mcq",
      "objective": "O4",
      "stem": "What is the core difference between a workflow and an agent?",
      "options": [
        {"id": "a", "text": "An agent can use tools, while a workflow never calls a model"},
        {"id": "b", "text": "An agent uses a larger model, while a workflow uses a smaller one"},
        {"id": "c", "text": "In an agent the model picks the next step; in a workflow, code does"},
        {"id": "d", "text": "An agent runs many steps, while a workflow runs exactly one step"}
      ]
    },
    {
      "id": "q2",
      "type": "mcq",
      "objective": "O4",
      "stem": "Your booking feature always runs check_calendar, then reserve_slot, then one model call that writes the confirmation message. Is this a workflow or an agent?",
      "options": [
        {"id": "a", "text": "An agent, because a model writes part of the output"},
        {"id": "b", "text": "A workflow, because the code fixes the order of the steps"},
        {"id": "c", "text": "An agent, because it calls tools such as check_calendar"},
        {"id": "d", "text": "An agent, because it runs more than one step per request"}
      ]
    },
    {
      "id": "q3",
      "type": "mcq",
      "objective": "O4",
      "stem": "Which makerspace request is the best fit for an agent rather than a fixed workflow?",
      "options": [
        {"id": "a", "text": "\"Reserve the 3D printer for Friday at 2 pm.\""},
        {"id": "b", "text": "\"What are the laser cutter's opening hours?\""},
        {"id": "c", "text": "\"Remind me an hour before my booking starts.\""},
        {"id": "d", "text": "\"Why are my acrylic cuts melting at the edges?\""}
      ]
    },
    {
      "id": "q4",
      "type": "numeric",
      "objective": "O4",
      "stem": "A fixed workflow makes 2 model calls per request. An agent doing the same job averages 5 model calls per request. Over 200 requests, how many more model calls does the agent make?",
      "unit": "model calls"
    },
    {
      "id": "q5",
      "type": "mcq",
      "objective": "O4",
      "stem": "One model call labels each student message \"booking\", \"manual question\" or \"other\". Code then runs a fixed handler for that label. Who owns the control flow?",
      "options": [
        {"id": "a", "text": "The code, because the paths are fixed and the model only picks a label"},
        {"id": "b", "text": "The model, because the label it picks decides which path runs"},
        {"id": "c", "text": "Both equally, because each of them makes a choice about the next step"},
        {"id": "d", "text": "The handlers, because each one runs its own steps after the label"}
      ]
    },
    {
      "id": "q6",
      "type": "short",
      "objective": "O4",
      "stem": "Booking a machine always means checking the calendar, reserving the slot, then confirming. In one sentence, why is a fixed workflow a better choice than an agent here?"
    }
  ]
}
EOF
cat > drafts/0002-key.json <<'EOF'
{
  "id": "0002",
  "items": [
    {
      "id": "q1",
      "answer": "c",
      "rationale": "Who owns the control flow is the difference: in a workflow the developer's code fixes the steps and their order, in an agent the model chooses the next step at run time. Both can call models and tools, and size or step count does not define either.",
      "distractors": {"a": "M7", "b": "M8", "d": "M9"}
    },
    {
      "id": "q2",
      "answer": "b",
      "rationale": "The code fixes the order (calendar, reserve, confirm) and the model only writes text inside one step, so the code owns the control flow: a workflow. Using a model, using tools or having several steps does not make something an agent.",
      "distractors": {"a": "M7", "c": "M7", "d": "M9"}
    },
    {
      "id": "q3",
      "answer": "d",
      "rationale": "Diagnosing melted edges is open-ended: which manual pages, checks or follow-up questions are needed cannot be known in advance, so the model must choose the steps. The other three have known, repeatable steps that code can run.",
      "distractors": {"a": "M7", "b": "M7", "c": "M7"}
    },
    {
      "id": "q4",
      "answer": 600,
      "tolerance": 0,
      "rationale": "The difference is 5 - 2 = 3 extra calls per request, and 3 x 200 = 600. This is part of why a fixed workflow is cheaper when the steps are known in advance."
    },
    {
      "id": "q5",
      "answer": "a",
      "rationale": "The model's only job is to pick a label; the paths are written in advance and code runs them, so the code owns the control flow and this is a workflow (a routing workflow). A model making a choice inside a fixed structure does not make it an agent.",
      "distractors": {"b": "M10", "c": "M10", "d": "M10"}
    },
    {
      "id": "q6",
      "answer": "The steps are known in advance and the same every time, so code can run them more cheaply and predictably than a model choosing them.",
      "accepted": [
        "The steps are fixed and known ahead of time, so there is no need for the model to decide them, which saves cost and is more reliable.",
        "It is cheaper and more predictable because the order never changes.",
        "The order of steps never varies, so code can run it reliably with fewer model calls."
      ],
      "rationale": "Full credit names that the steps are known or fixed in advance and gives a benefit (lower cost, more predictable or reliable). Saying only that agents are worse or newer, or that the model might make a mistake with no mention of fixed steps, is partial or wrong; thinking an agent is always the better choice shows M11."
    }
  ]
}
EOF
